def effect(ctx, hand_type, scored_cards, played_cards, held_cards, game, joker):
    if len(played_cards) < 4:
        return
    ranks = [rank_value(c) for c in played_cards]
    suits = [c.suit for c in played_cards]
    # 检查至少4张连续点数（忽略重复）
    unique_ranks = sorted(set(ranks))
    has_straight = False
    for i in range(len(unique_ranks) - 3):
        if unique_ranks[i+3] - unique_ranks[i] == 3:
            has_straight = True
            break
    if not has_straight:
        return
    # 检查至少3张同花色
    suit_counts = {}
    for s in suits:
        suit_counts[s] = suit_counts.get(s, 0) + 1
    if max(suit_counts.values()) >= 3:
        ctx.x_mult *= 2
        ctx.chips += 40
